{
  "headline": "Leucovorin calcium is not on FDA's current shortage list as of 2026-10-21; the earliest posting in FDA's database is 2012-01-01",
  "headline_cites": ["D9", "D8"],
  "sentences": [
    {
      "text": "FDA's shortage list shows leucovorin calcium is not currently listed as of 2026-10-21.",
      "cites": ["D9"]
    },
    {
      "text": "The earliest posting in FDA's database is 2012-01-01, which is the database start date.",
      "cites": ["D8"]
    },
    {
      "text": "Corvale East has 2.7 days of the 50 mg/5 mL injection on hand, Corvale General has 23.2 days, and Corvale Lakeside has 24.5 days.",
      "cites": ["D1", "D2", "D3"]
    },
    {
      "text": "The 50 mg/5 mL vials at all three sites are supplied by Sagent Pharmaceuticals (NDC 25021081310).",
      "cites": ["E3", "E6", "E7"]
    },
    {
      "text": "Sagent Pharmaceuticals is the named manufacturer on the label for this NDC.",
      "cites": ["E17"]
    },
    {
      "text": "The top-ranked option is to transfer 8 vials of 50 mg/5 mL from Corvale Lakeside to Corvale East, which would raise Corvale East to 5 days on hand while Corvale Lakeside retains 14 days.",
      "cites": ["D10"]
    },
    {
      "text": "This transfer requires a pharmacy director transfer request.",
      "cites": ["D10"]
    }
  ]
}
